WITH ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY device_code ORDER BY pressure DESC NULLS LAST, id) AS dedup_rank FROM device_readings QUALIFY dedup_rank = 1) SELECT CASE WHEN temp_c >= 34.8 THEN 'HIGH' ELSE 'LOW' END AS temp_c_tier, (UNIX_TIMESTAMP(MAX(reading_ts)) - UNIX_TIMESTAMP(MIN(reading_ts))) / 60 AS duration_min, PERCENTILE_APPROX(status_bits, 0.95) AS status_bits_p95, SORT_ARRAY(COLLECT_SET(device_code)) AS device_code_list, STDDEV_SAMP(humidity) AS humidity_stddev, SUM(humidity) AS total_humidity, STDDEV_SAMP(humidity) AS humidity_stddev_2 FROM ranked GROUP BY temp_c_tier HAVING status_bits_p95 >= 0 ORDER BY duration_min DESC NULLS FIRST;
